package com.smartretail.billing.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { private final SecretKey key; public JwtService(@Value("${jwt.secret}") String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} private Claims claims(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();} public boolean valid(String t){try{return claims(t).getExpiration().after(new Date());}catch(JwtException|IllegalArgumentException e){return false;}} public String username(String t){try{return claims(t).getSubject();}catch(JwtException|IllegalArgumentException e){return null;}} public Long businessId(String t){try{return claims(t).get("businessId",Long.class);}catch(JwtException|IllegalArgumentException e){return null;}} }
